FUNCTION UNDER TEST:
Name: inorder
Signature: void inorder(struct node* root)
Description: /**
 * @brief Traverse a binary search tree in-order and print keys.
 *
 * Recursively visits nodes in ascending order, printing each key to
 * standard output separated by spaces. Does nothing if the tree is empty
 * (root is NULL).
 *
 * @param root Root of the binary search tree, or NULL for an empty tree.
 *
 * @return None.
 *
 * @note This function prints directly to stdout and does not allocate memory.
 */
Dependencies: inorder

FUNCTION IMPLEMENTATION:
```c
// C program for the function called inorder
// Contains target function implementation and dependency signatures

#include <stdio.h>
#include <stdlib.h>

struct node {
	int key;
	struct node *left, *right;
};

// Forward declarations for dependency functions

// Target function implementation
void inorder(struct node* root)
{
	if (root != NULL) {
		inorder(root->left);
		printf("%d ", root->key);
		inorder(root->right);
	}
}

```

